package com.finboost.bank.statement.parser.config.document.extraction;

/**
 * Indicates which extraction engine produced the structured transaction data
 * for a statement (or for an account aggregated from statements).
 */
public enum ExtractionMode {
    /**
     * The offline native (PDFBox based) transaction-table path produced the result.
     */
    NATIVE,
    /**
     * The remote ML (document intelligence) path produced the result.
     */
    ML,
    /**
     * The native path was attempted for a supported layout but did not succeed,
     * and the remote ML path was used as a fallback.
     */
    NATIVE_FALLBACK_ML
}

