package com.finboost.bank.statement.parser.service.document.extraction.offline;

import lombok.AllArgsConstructor;
import lombok.Data;

/**
 * A single axis-aligned ruling line (or thin filled rectangle edge) found in a PDF
 * page. Coordinates are expressed in inches with the origin at the top-left corner
 * of the page, matching the coordinate system used by the rest of the document
 * extraction pipeline.
 */
@Data
@AllArgsConstructor
public class PdfRulingLine {
    private float x1;
    private float y1;
    private float x2;
    private float y2;

    public boolean isHorizontal() {
        return Math.abs(y2 - y1) <= 0.02f && Math.abs(x2 - x1) > Math.abs(y2 - y1);
    }

    public boolean isVertical() {
        return Math.abs(x2 - x1) <= 0.02f && Math.abs(y2 - y1) > Math.abs(x2 - x1);
    }

    public float length() {
        float dx = x2 - x1;
        float dy = y2 - y1;
        return (float) Math.sqrt(dx * dx + dy * dy);
    }

    public float minX() { return Math.min(x1, x2); }
    public float maxX() { return Math.max(x1, x2); }
    public float minY() { return Math.min(y1, y2); }
    public float maxY() { return Math.max(y1, y2); }
}

