import lombok.Data;

import java.util.ArrayList;
import java.util.List;

/**
 * Raw native (offline) content of a single PDF page: extracted words, ruling lines
 * and the page dimensions. All coordinates are in inches from the top-left corner.
 */
@Data
public class NativePdfPageContent {
    private int pageNumber;
    private double width;
    private double height;
    private String content = "";
    private List<Word> words = new ArrayList<>();
    private List<PdfRulingLine> horizontalRulings = new ArrayList<>();
    private List<PdfRulingLine> verticalRulings = new ArrayList<>();
}

package com.finboost.bank.statement.parser.service.document.extraction.offline;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.text.PDFTextStripper;
import org.apache.pdfbox.text.TextPosition;
import org.springframework.stereotype.Service;

import java.awt.geom.Point2D;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

/**
 * Offline PDF content reader used by the native transaction-table extraction path.
 * Extracts words (with bounding polygons) and axis-aligned ruling lines for each
 * page of an electronic PDF using PDFBox only. All coordinates are converted to
 * inches with the origin at the top-left corner of the page, matching the
 * coordinate system produced by the remote ML extraction mapper.
 */
@Service
@Slf4j
public class NativePdfContentReader {

    private static final float POINTS_PER_INCH = 72.0f;
    /** Horizontal gap (in inches) beyond which glyph runs are split into separate words. */
    private static final float WORD_GAP_THRESHOLD_INCHES = 0.055f;
    /** Minimum length (in inches) for a segment to be considered a ruling line. */
    private static final float MIN_RULING_LENGTH_INCHES = 0.05f;

    public List<NativePdfPageContent> read(File pdfFile) throws IOException {
        List<NativePdfPageContent> pages = new LinkedList<>();

        try (PDDocument document = Loader.loadPDF(pdfFile)) {
            int pageCount = document.getNumberOfPages();
            for (int pageIndex = 0; pageIndex < pageCount; pageIndex++) {
                PDPage page = document.getPage(pageIndex);
                PDRectangle cropBox = page.getCropBox();

                NativePdfPageContent pageContent = new NativePdfPageContent();
                pageContent.setPageNumber(pageIndex + 1);
                pageContent.setWidth(cropBox.getWidth() / POINTS_PER_INCH);
                pageContent.setHeight(cropBox.getHeight() / POINTS_PER_INCH);

                // Extract words
                WordExtractor wordExtractor = new WordExtractor(pageIndex + 1);
                wordExtractor.setStartPage(pageIndex + 1);
                wordExtractor.setEndPage(pageIndex + 1);
                String textContent = wordExtractor.getText(document);
                pageContent.setContent(textContent != null ? textContent : "");
                pageContent.setWords(wordExtractor.getWords());

                // Extract ruling lines
                try {
                    RulingCollector rulingCollector = new RulingCollector(page, cropBox);
                    rulingCollector.processPage(page);
                    for (PdfRulingLine ruling : rulingCollector.getRulings()) {
                        if (ruling.length() < MIN_RULING_LENGTH_INCHES) {
                            continue;
                        }
                        if (ruling.isHorizontal()) {
                            pageContent.getHorizontalRulings().add(ruling);
                        } else if (ruling.isVertical()) {
                            pageContent.getVerticalRulings().add(ruling);
                        }
                    }
                } catch (Exception e) {
                    log.warn("Failed to collect ruling lines from page {}: {}", pageIndex + 1, e.getMessage());
                }

                pages.add(pageContent);
            }
        }

        return pages;
    }

    /**
     * Splits page text positions into words, keeping bounding polygons in inches
     * from the top-left page corner. Polygon convention: (x1,y1) top-left,
     * (x2,y2) top-right, (x3,y3) bottom-right, (x4,y4) bottom-left.
     */
    private static final class WordExtractor extends PDFTextStripper {
        private final int pageNumber;
        private final List<Word> words = new ArrayList<>();
        private final List<TextPosition> currentRun = new ArrayList<>();
        private int wordIndex = 1;

        private WordExtractor(int pageNumber) throws IOException {
            this.pageNumber = pageNumber;
            setSortByPosition(true);
        }

        private List<Word> getWords() {
            return words;
        }

        @Override
        protected void writeString(String text, List<TextPosition> textPositions) throws IOException {
            for (TextPosition position : textPositions) {
                String unicode = position.getUnicode();
                if (unicode == null || unicode.trim().isEmpty()) {
                    flushRun();
                    continue;
                }
                if (!currentRun.isEmpty()) {
                    TextPosition previous = currentRun.get(currentRun.size() - 1);
                    float previousEndX = (previous.getXDirAdj() + previous.getWidthDirAdj()) / POINTS_PER_INCH;
                    float currentStartX = position.getXDirAdj() / POINTS_PER_INCH;
                    float previousBaseline = previous.getYDirAdj() / POINTS_PER_INCH;
                    float currentBaseline = position.getYDirAdj() / POINTS_PER_INCH;
                    boolean sameLine = Math.abs(currentBaseline - previousBaseline) <= 0.04f;
                    if (!sameLine || (currentStartX - previousEndX) > WORD_GAP_THRESHOLD_INCHES
                            || currentStartX < previousEndX - 0.15f) {
                        flushRun();
                    }
                }
                currentRun.add(position);
            }
            flushRun();
            super.writeString(text, textPositions);
        }

        @Override
        protected void writeLineSeparator() throws IOException {
            flushRun();
            super.writeLineSeparator();
        }

        @Override
        protected void endPage(PDPage page) throws IOException {
            flushRun();
            super.endPage(page);
        }

        private void flushRun() {
            if (currentRun.isEmpty()) {
                return;
            }

            StringBuilder contentBuilder = new StringBuilder();
            float minX = Float.MAX_VALUE;
            float maxX = -Float.MAX_VALUE;
            float minY = Float.MAX_VALUE;
            float maxY = -Float.MAX_VALUE;

            for (TextPosition position : currentRun) {
                contentBuilder.append(position.getUnicode());
                float startX = position.getXDirAdj() / POINTS_PER_INCH;
                float endX = (position.getXDirAdj() + position.getWidthDirAdj()) / POINTS_PER_INCH;
                float baselineY = position.getYDirAdj() / POINTS_PER_INCH;
                float glyphHeight = Math.max(position.getHeightDir(), position.getFontSizeInPt() * 0.7f) / POINTS_PER_INCH;
                float topY = baselineY - glyphHeight;

                minX = Math.min(minX, startX);
                maxX = Math.max(maxX, endX);
                minY = Math.min(minY, topY);
                maxY = Math.max(maxY, baselineY);
            }
            currentRun.clear();

            String content = contentBuilder.toString().trim();
            if (content.isEmpty()) {
                return;
            }

            Word word = new Word(content,
                    minX, minY,
                    maxX, minY,
                    maxX, maxY,
                    minX, maxY,
                    pageNumber,
                    maxX - minX,
                    maxY - minY,
                    pageNumber,
                    wordIndex++);
            words.add(word);
        }
    }

    /**
     * Collects stroked line segments and thin filled rectangles as ruling lines.
     */
    private static final class RulingCollector extends PDFGraphicsStreamEngine {
        private final PDRectangle cropBox;
        private final List<PdfRulingLine> rulings = new ArrayList<>();
        private final List<float[]> currentPathSegments = new ArrayList<>();
        private Point2D.Float currentPoint;
        private Point2D.Float subPathStart;

        private RulingCollector(PDPage page, PDRectangle cropBox) {
            super(page);
            this.cropBox = cropBox;
        }

        private List<PdfRulingLine> getRulings() {
            return rulings;
        }

        private float toInchX(double x) {
            return (float) ((x - cropBox.getLowerLeftX()) / POINTS_PER_INCH);
        }

        private float toInchY(double y) {
            return (float) ((cropBox.getUpperRightY() - y) / POINTS_PER_INCH);
        }

        @Override
        public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            addSegment(p0, p1);
            addSegment(p1, p2);
            addSegment(p2, p3);
            addSegment(p3, p0);
            currentPoint = new Point2D.Float((float) p0.getX(), (float) p0.getY());
            subPathStart = currentPoint;
        }

        private void addSegment(Point2D from, Point2D to) {
            if (from == null || to == null) {
                return;
            }
            currentPathSegments.add(new float[]{
                    (float) from.getX(), (float) from.getY(),
                    (float) to.getX(), (float) to.getY()});
        }

        @Override
        public void drawImage(PDImage pdImage) {
            // Images are ignored by the native path.
        }

        @Override
        public void clip(int windingRule) {
            // Clipping paths are not treated as rulings.
            currentPathSegments.clear();
        }

        @Override
        public void moveTo(float x, float y) {
            currentPoint = new Point2D.Float(x, y);
            subPathStart = currentPoint;
        }

        @Override
        public void lineTo(float x, float y) {
            Point2D.Float next = new Point2D.Float(x, y);
            if (currentPoint != null) {
                addSegment(currentPoint, next);
            }
            currentPoint = next;
        }

        @Override
        public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) {
            // Curves are not rulings; just advance the current point.
            currentPoint = new Point2D.Float(x3, y3);
        }

        @Override
        public Point2D getCurrentPoint() {
            return currentPoint;
        }

        @Override
        public void closePath() {
            if (currentPoint != null && subPathStart != null) {
                addSegment(currentPoint, subPathStart);
                currentPoint = subPathStart;
            }
        }

        @Override
        public void endPath() {
            currentPathSegments.clear();
        }

        @Override
        public void strokePath() {
            commitSegments();
        }

        @Override
        public void fillPath(int windingRule) {
            // Thin filled rectangles frequently represent table rulings.
            commitSegments();
        }

        @Override
        public void fillAndStrokePath(int windingRule) {
            commitSegments();
        }

        @Override
        public void shadingFill(COSName shadingName) {
            currentPathSegments.clear();
        }

        private void commitSegments() {
            for (float[] segment : currentPathSegments) {
                float x1 = toInchX(segment[0]);
                float y1 = toInchY(segment[1]);
                float x2 = toInchX(segment[2]);
                float y2 = toInchY(segment[3]);
                PdfRulingLine ruling = new PdfRulingLine(x1, y1, x2, y2);
                if (ruling.isHorizontal() || ruling.isVertical()) {
                    rulings.add(ruling);
                }
            }
            currentPathSegments.clear();
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.offline;

import com.finboost.bank.statement.parser.config.document.extraction.NativeTablePolicy;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.ColumnTypeIdentifier;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.HistogramColumnDetectionService;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Composes structured transaction {@link Table}s from raw native PDF page content
 * using one of the offline {@link NativeTablePolicy} strategies:
 *
 * <ul>
 *     <li>{@code BORDERED_GRID}: cells are derived from the intersections of the
 *     horizontal and vertical ruling lines of a fully ruled table.</li>
 *     <li>{@code BOX_GUIDED}: columns are derived from long vertical separator
 *     lines (the box), rows are recovered from text baselines inside the box.</li>
 *     <li>{@code TEXT_ALIGNED_ROW_SELECTED}: transaction rows are selected below a
 *     detected header line using date/amount anchors, and columns are recovered
 *     from the whitespace alignment of the selected rows.</li>
 * </ul>
 */
@Service
@Slf4j
public class NativeTransactionTableComposer {

    private static final float POSITION_CLUSTER_TOLERANCE = 0.035f;
    private static final float MIN_HORIZONTAL_RULING_COVERAGE = 0.9f;
    private static final float MIN_VERTICAL_RULING_COVERAGE = 0.28f;
    private static final float MIN_BOX_SEPARATOR_HEIGHT = 0.7f;
    private static final float HORIZONTAL_BAND_BREAK_GAP = 1.25f;
    private static final float LINE_GROUP_TOLERANCE = 0.065f;
    private static final float CONTINUATION_ROW_MAX_GAP = 0.35f;

    private static final Pattern FOOTER_STOP_PATTERN = Pattern.compile(
            "(statement\\s+summary|grand\\s+total|page\\s+total|carried\\s+forward|brought\\s+forward|"
                    + "end\\s+of\\s+(the\\s+)?statement|closing\\s+balance|opening\\s+balance\\s*:|"
                    + "transaction\\s+total|\\btotal\\b\\s*:?$|legends|abbreviations|unless\\s+the\\s+constituent)",
            Pattern.CASE_INSENSITIVE);

    private static final List<List<String>> HEADER_KEYWORD_GROUPS = List.of(
            List.of("date"),
            List.of("particulars", "narration", "description", "details", "remarks", "transactions"),
            List.of("debit", "withdrawal", "withdrawals", "dr"),
            List.of("credit", "deposit", "deposits", "cr"),
            List.of("balance"),
            List.of("chq", "cheque", "ref", "utr", "instrument"));

    @Setter(onMethod_ = @Autowired)
    private HistogramColumnDetectionService histogramColumnDetectionService;

    private final ColumnTypeIdentifier contentTypeIdentifier = new ColumnTypeIdentifier();

    /**
     * Composes candidate transaction tables for a single page using the given policy.
     *
     * @return map of table index to table; empty map when the layout does not match the policy
     */
    public Map<Integer, Table> composeTables(NativePdfPageContent page, NativeTablePolicy policy) {
        try {
            switch (policy) {
                case BORDERED_GRID:
                    return composeBorderedGridTables(page);
                case BOX_GUIDED:
                    return composeBoxGuidedTables(page);
                case TEXT_ALIGNED_ROW_SELECTED:
                    return composeTextAlignedTables(page);
                default:
                    return new LinkedHashMap<>();
            }
        } catch (Exception e) {
            log.warn("Native table composition failed on page {} for policy {}: {}",
                    page.getPageNumber(), policy, e.getMessage());
            return new LinkedHashMap<>();
        }
    }

    // ------------------------------------------------------------------
    // BORDERED_GRID
    // ------------------------------------------------------------------

    private Map<Integer, Table> composeBorderedGridTables(NativePdfPageContent page) {
        Map<Integer, Table> tables = new LinkedHashMap<>();

        List<Boundary> horizontals = clusterBoundaries(page.getHorizontalRulings(), true);
        horizontals.removeIf(boundary -> boundary.getCovered() < MIN_HORIZONTAL_RULING_COVERAGE);
        horizontals.sort(Comparator.comparingDouble(Boundary::getPosition));

        List<Boundary> verticals = clusterBoundaries(page.getVerticalRulings(), false);
        verticals.removeIf(boundary -> boundary.getCovered() < MIN_VERTICAL_RULING_COVERAGE);
        verticals.sort(Comparator.comparingDouble(Boundary::getPosition));

        if (horizontals.size() < 3 || verticals.size() < 3) {
            return tables;
        }

        // Group horizontal boundaries into contiguous bands (individual tables)
        List<List<Boundary>> bands = new ArrayList<>();
        List<Boundary> currentBand = new ArrayList<>();
        for (Boundary horizontal : horizontals) {
            if (!currentBand.isEmpty()
                    && horizontal.getPosition() - currentBand.get(currentBand.size() - 1).getPosition() > HORIZONTAL_BAND_BREAK_GAP) {
                bands.add(currentBand);
                currentBand = new ArrayList<>();
            }
            currentBand.add(horizontal);
        }
        if (!currentBand.isEmpty()) {
            bands.add(currentBand);
        }

        int tableIndex = 0;
        for (List<Boundary> band : bands) {
            if (band.size() < 3) {
                continue;
            }

            float bandTop = band.get(0).getPosition();
            float bandBottom = band.get(band.size() - 1).getPosition();
            float bandHeight = bandBottom - bandTop;
            if (bandHeight < 0.3f) {
                continue;
            }

            float bandMinX = Float.MAX_VALUE;
            float bandMaxX = -Float.MAX_VALUE;
            for (Boundary boundary : band) {
                bandMinX = Math.min(bandMinX, boundary.getExtentMin());
                bandMaxX = Math.max(bandMaxX, boundary.getExtentMax());
            }

            // Vertical boundaries that belong to this band
            List<Float> columnBoundaries = new ArrayList<>();
            for (Boundary vertical : verticals) {
                if (vertical.getPosition() < bandMinX - 0.06f || vertical.getPosition() > bandMaxX + 0.06f) {
                    continue;
                }
                float overlap = Math.min(vertical.getExtentMax(), bandBottom) - Math.max(vertical.getExtentMin(), bandTop);
                if (overlap >= Math.min(bandHeight * 0.3f, 1.5f)) {
                    columnBoundaries.add(vertical.getPosition());
                }
            }
            if (columnBoundaries.size() < 3) {
                continue;
            }
            columnBoundaries.sort(Comparator.naturalOrder());

            List<Float> rowBoundaries = new ArrayList<>();
            for (Boundary boundary : band) {
                rowBoundaries.add(boundary.getPosition());
            }

            Table table = buildGridTable(page, columnBoundaries, rowBoundaries);
            if (table != null) {
                tables.put(tableIndex++, table);
            }
        }

        return tables;
    }

    // ------------------------------------------------------------------
    // BOX_GUIDED
    // ------------------------------------------------------------------

    private Map<Integer, Table> composeBoxGuidedTables(NativePdfPageContent page) {
        Map<Integer, Table> tables = new LinkedHashMap<>();

        List<Boundary> verticals = clusterBoundaries(page.getVerticalRulings(), false);
        verticals.removeIf(boundary -> boundary.getCovered() < MIN_BOX_SEPARATOR_HEIGHT);
        if (verticals.size() < 4) {
            return tables;
        }

        // Seed the box with the tallest vertical separator and keep separators that
        // share most of its vertical extent.
        Boundary tallest = verticals.stream()
                .max(Comparator.comparingDouble(boundary -> boundary.getExtentMax() - boundary.getExtentMin()))
                .orElse(null);
        if (tallest == null) {
            return tables;
        }

        List<Boundary> group = new ArrayList<>();
        for (Boundary vertical : verticals) {
            float height = vertical.getExtentMax() - vertical.getExtentMin();
            float overlap = Math.min(vertical.getExtentMax(), tallest.getExtentMax())
                    - Math.max(vertical.getExtentMin(), tallest.getExtentMin());
            if (overlap >= 0.5f * Math.min(height, tallest.getExtentMax() - tallest.getExtentMin())) {
                group.add(vertical);
            }
        }
        if (group.size() < 4) {
            return tables;
        }
        group.sort(Comparator.comparingDouble(Boundary::getPosition));

        float regionTop = Float.MAX_VALUE;
        float regionBottom = -Float.MAX_VALUE;
        for (Boundary boundary : group) {
            regionTop = Math.min(regionTop, boundary.getExtentMin());
            regionBottom = Math.max(regionBottom, boundary.getExtentMax());
        }

        List<Float> columnBoundaries = new ArrayList<>();
        for (Boundary boundary : group) {
            columnBoundaries.add(boundary.getPosition());
        }

        // Rows are recovered from text baselines inside the box.
        List<TextLineGroup> lines = groupWordsIntoLines(
                filterWords(page.getWords(),
                        columnBoundaries.get(0) - 0.05f,
                        columnBoundaries.get(columnBoundaries.size() - 1) + 0.05f,
                        regionTop - 0.02f, regionBottom + 0.02f));
        if (lines.size() < 2) {
            return tables;
        }

        List<Float> rowBoundaries = new ArrayList<>();
        rowBoundaries.add(regionTop);
        for (int i = 0; i < lines.size() - 1; i++) {
            rowBoundaries.add((lines.get(i).getMaxY() + lines.get(i + 1).getMinY()) / 2.0f);
        }
        rowBoundaries.add(regionBottom);

        Table table = buildGridTable(page, columnBoundaries, rowBoundaries);
        if (table != null) {
            tables.put(0, table);
        }
        return tables;
    }

    // ------------------------------------------------------------------
    // TEXT_ALIGNED_ROW_SELECTED
    // ------------------------------------------------------------------

    private Map<Integer, Table> composeTextAlignedTables(NativePdfPageContent page) {
        Map<Integer, Table> tables = new LinkedHashMap<>();

        List<TextLineGroup> lines = groupWordsIntoLines(page.getWords());
        if (lines.size() < 3) {
            return tables;
        }

        // 1. Detect the transaction table header line.
        int headerLineIndex = -1;
        for (int i = 0; i < lines.size(); i++) {
            if (headerScore(lines.get(i).getText()) >= 3) {
                headerLineIndex = i;
                break;
            }
        }

        // 2. Select the transaction rows following the header (or the date anchored
        //    rows at the top of a continuation page).
        List<TextLineGroup> selectedLines = new ArrayList<>();
        boolean anchorFound = false;
        float previousLineBottom = Float.MAX_VALUE;
        int startIndex = headerLineIndex >= 0 ? headerLineIndex + 1 : 0;
        for (int i = startIndex; i < lines.size(); i++) {
            TextLineGroup line = lines.get(i);
            String text = line.getText();
            boolean hasDate = containsDateToken(line);
            boolean hasAmount = containsAmountToken(line);

            if (anchorFound && FOOTER_STOP_PATTERN.matcher(text).find() && !hasDate) {
                break;
            }

            if (hasDate && hasAmount) {
                selectedLines.add(line);
                anchorFound = true;
                previousLineBottom = line.getMaxY();
            } else if (anchorFound && line.getMinY() - previousLineBottom <= CONTINUATION_ROW_MAX_GAP
                    && !FOOTER_STOP_PATTERN.matcher(text).find()) {
                selectedLines.add(line);
                previousLineBottom = line.getMaxY();
            } else if (anchorFound) {
                break;
            }
        }

        if (selectedLines.isEmpty() || (headerLineIndex < 0 && selectedLines.size() < 2)) {
            return tables;
        }

        List<TextLineGroup> tableLines = new ArrayList<>();
        if (headerLineIndex >= 0) {
            tableLines.add(lines.get(headerLineIndex));
        }
        tableLines.addAll(selectedLines);

        float minX = Float.MAX_VALUE;
        float maxX = -Float.MAX_VALUE;
        float minY = Float.MAX_VALUE;
        float maxY = -Float.MAX_VALUE;
        for (TextLineGroup line : tableLines) {
            minX = Math.min(minX, line.getMinX());
            maxX = Math.max(maxX, line.getMaxX());
            minY = Math.min(minY, line.getMinY());
            maxY = Math.max(maxY, line.getMaxY());
        }

        // 3. Build a single-column table where each selected line is a row and let
        //    the whitespace histogram split the aligned columns.
        Table table = new Table();
        table.setPageNumber(page.getPageNumber());
        setTablePolygon(table, minX - 0.02f, minY - 0.02f, maxX + 0.02f, maxY + 0.02f);
        table.setSpanOffset(0);
        table.setSpanLength(0);
        table.setColType(new ArrayList<>());
        table.setTxnColType(new ArrayList<>());

        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
        int rowIndex = 0;
        for (TextLineGroup line : tableLines) {
            TableCell cell = new TableCell();
            cell.setRowindex(rowIndex);
            cell.setColindex(0);
            cell.setRowspan(1);
            cell.setColspan(1);
            cell.setWords(new ArrayList<>(line.getWords()));
            cell.setX1(minX);
            cell.setY1(line.getMinY());
            cell.setX2(maxX);
            cell.setY2(line.getMinY());
            cell.setX3(maxX);
            cell.setY3(line.getMaxY());
            cell.setX4(minX);
            cell.setY4(line.getMaxY());

            Map<Integer, TableCell> row = new LinkedHashMap<>();
            row.put(0, cell);
            cells.put(rowIndex++, row);
        }
        table.setCells(cells);
        table.setTotalRows(cells.size());
        table.setTotalColumns(1);

        histogramColumnDetectionService.identifyColumnRanges(table);
        if (table.getTotalColumns() == null || table.getTotalColumns() < 4) {
            return tables;
        }

        tables.put(0, table);
        return tables;
    }

    private int headerScore(String lineText) {
        String normalized = lineText.toLowerCase(Locale.ROOT);
        int score = 0;
        for (List<String> group : HEADER_KEYWORD_GROUPS) {
            for (String keyword : group) {
                if (normalized.matches(".*\\b" + Pattern.quote(keyword) + "\\b.*")) {
                    score++;
                    break;
                }
            }
        }
        return score;
    }

    private boolean containsDateToken(TextLineGroup line) {
        for (Word word : line.getWords()) {
            if (contentTypeIdentifier.isDateType(word.getContent())) {
                return true;
            }
        }
        return false;
    }

    private boolean containsAmountToken(TextLineGroup line) {
        for (Word word : line.getWords()) {
            String content = word.getContent();
            if (content != null && content.matches(".*\\d.*") && contentTypeIdentifier.isAmountType(content)) {
                return true;
            }
        }
        return false;
    }

    // ------------------------------------------------------------------
    // Shared helpers
    // ------------------------------------------------------------------

    /**
     * Builds a table from explicit column and row boundaries by assigning each word
     * of the page to the cell containing its center point.
     */
    private Table buildGridTable(NativePdfPageContent page, List<Float> columnBoundaries, List<Float> rowBoundaries) {
        if (columnBoundaries.size() < 2 || rowBoundaries.size() < 2) {
            return null;
        }

        float tableLeft = columnBoundaries.get(0);
        float tableRight = columnBoundaries.get(columnBoundaries.size() - 1);
        float tableTop = rowBoundaries.get(0);
        float tableBottom = rowBoundaries.get(rowBoundaries.size() - 1);

        int columnCount = columnBoundaries.size() - 1;
        int rawRowCount = rowBoundaries.size() - 1;

        List<Word> tableWords = filterWords(page.getWords(),
                tableLeft - 0.02f, tableRight + 0.02f, tableTop - 0.01f, tableBottom + 0.01f);
        if (tableWords.isEmpty()) {
            return null;
        }

        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
        int effectiveRowIndex = 0;
        for (int rawRow = 0; rawRow < rawRowCount; rawRow++) {
            float rowTop = rowBoundaries.get(rawRow);
            float rowBottom = rowBoundaries.get(rawRow + 1);

            Map<Integer, TableCell> row = new LinkedHashMap<>();
            boolean rowHasWords = false;
            for (int column = 0; column < columnCount; column++) {
                float columnLeft = column == 0 ? tableLeft - 0.02f : columnBoundaries.get(column);
                float columnRight = column == columnCount - 1 ? tableRight + 0.02f : columnBoundaries.get(column + 1);

                TableCell cell = new TableCell();
                cell.setRowindex(effectiveRowIndex);
                cell.setColindex(column);
                cell.setRowspan(1);
                cell.setColspan(1);
                cell.setX1(columnBoundaries.get(column));
                cell.setY1(rowTop);
                cell.setX2(columnBoundaries.get(column + 1));
                cell.setY2(rowTop);
                cell.setX3(columnBoundaries.get(column + 1));
                cell.setY3(rowBottom);
                cell.setX4(columnBoundaries.get(column));
                cell.setY4(rowBottom);

                List<Word> cellWords = new ArrayList<>();
                for (Word word : tableWords) {
                    float centerX = (word.getX1() + word.getX3()) / 2.0f;
                    float centerY = (word.getY1() + word.getY3()) / 2.0f;
                    if (centerX >= columnLeft && centerX < columnRight
                            && centerY >= rowTop && centerY < rowBottom) {
                        cellWords.add(word);
                        rowHasWords = true;
                    }
                }
                cell.setWords(cellWords);
                row.put(column, cell);
            }

            if (rowHasWords) {
                cells.put(effectiveRowIndex++, row);
            }
        }

        if (cells.size() < 2) {
            return null;
        }

        Table table = new Table();
        table.setPageNumber(page.getPageNumber());
        setTablePolygon(table, tableLeft, tableTop, tableRight, tableBottom);
        table.setSpanOffset(0);
        table.setSpanLength(0);
        table.setColType(new ArrayList<>());
        table.setTxnColType(new ArrayList<>());
        table.setCells(cells);
        table.setTotalRows(cells.size());
        table.setTotalColumns(columnCount);
        return table;
    }

    private void setTablePolygon(Table table, float left, float top, float right, float bottom) {
        table.setX1(left);
        table.setY1(top);
        table.setX2(right);
        table.setY2(top);
        table.setX3(right);
        table.setY3(bottom);
        table.setX4(left);
        table.setY4(bottom);
    }

    private List<Word> filterWords(List<Word> words, float minX, float maxX, float minY, float maxY) {
        List<Word> filtered = new ArrayList<>();
        if (words == null) {
            return filtered;
        }
        for (Word word : words) {
            float centerX = (word.getX1() + word.getX3()) / 2.0f;
            float centerY = (word.getY1() + word.getY3()) / 2.0f;
            if (centerX >= minX && centerX <= maxX && centerY >= minY && centerY <= maxY) {
                filtered.add(word);
            }
        }
        return filtered;
    }

    /**
     * Groups words into visual text lines by their vertical center.
     */
    private List<TextLineGroup> groupWordsIntoLines(List<Word> words) {
        List<TextLineGroup> lines = new ArrayList<>();
        if (words == null || words.isEmpty()) {
            return lines;
        }

        List<Word> sorted = new ArrayList<>(words);
        sorted.sort(Comparator.comparingDouble(word -> (word.getY1() + word.getY3()) / 2.0f));

        TextLineGroup currentLine = null;
        for (Word word : sorted) {
            float centerY = (word.getY1() + word.getY3()) / 2.0f;
            if (currentLine == null || centerY - currentLine.getCenterY() > LINE_GROUP_TOLERANCE) {
                currentLine = new TextLineGroup();
                lines.add(currentLine);
            }
            currentLine.add(word, centerY);
        }

        for (TextLineGroup line : lines) {
            line.getWords().sort(Comparator.comparingDouble(Word::getX1));
        }
        return lines;
    }

    /**
     * Clusters ruling lines into logical boundaries by their axis position.
     *
     * @param horizontal true when the rulings are horizontal (clustered by y position)
     */
    private List<Boundary> clusterBoundaries(List<PdfRulingLine> rulings, boolean horizontal) {
        List<Boundary> boundaries = new ArrayList<>();
        if (rulings == null || rulings.isEmpty()) {
            return boundaries;
        }

        List<PdfRulingLine> sorted = new ArrayList<>(rulings);
        sorted.sort(Comparator.comparingDouble(ruling ->
                horizontal ? (ruling.getY1() + ruling.getY2()) / 2.0f : (ruling.getX1() + ruling.getX2()) / 2.0f));

        List<List<PdfRulingLine>> clusters = new ArrayList<>();
        List<PdfRulingLine> current = new ArrayList<>();
        float lastPosition = Float.NaN;
        for (PdfRulingLine ruling : sorted) {
            float position = horizontal ? (ruling.getY1() + ruling.getY2()) / 2.0f : (ruling.getX1() + ruling.getX2()) / 2.0f;
            if (!current.isEmpty() && position - lastPosition > POSITION_CLUSTER_TOLERANCE) {
                clusters.add(current);
                current = new ArrayList<>();
            }
            current.add(ruling);
            lastPosition = position;
        }
        if (!current.isEmpty()) {
            clusters.add(current);
        }

        for (List<PdfRulingLine> cluster : clusters) {
            float positionSum = 0f;
            List<float[]> intervals = new ArrayList<>();
            for (PdfRulingLine ruling : cluster) {
                positionSum += horizontal ? (ruling.getY1() + ruling.getY2()) / 2.0f : (ruling.getX1() + ruling.getX2()) / 2.0f;
                intervals.add(horizontal
                        ? new float[]{ruling.minX(), ruling.maxX()}
                        : new float[]{ruling.minY(), ruling.maxY()});
            }

            intervals.sort(Comparator.comparingDouble(interval -> interval[0]));
            float covered = 0f;
            float extentMin = intervals.get(0)[0];
            float extentMax = intervals.get(0)[1];
            float currentStart = intervals.get(0)[0];
            float currentEnd = intervals.get(0)[1];
            for (int i = 1; i < intervals.size(); i++) {
                float[] interval = intervals.get(i);
                extentMin = Math.min(extentMin, interval[0]);
                extentMax = Math.max(extentMax, interval[1]);
                if (interval[0] <= currentEnd + 0.05f) {
                    currentEnd = Math.max(currentEnd, interval[1]);
                } else {
                    covered += currentEnd - currentStart;
                    currentStart = interval[0];
                    currentEnd = interval[1];
                }
            }
            covered += currentEnd - currentStart;

            boundaries.add(new Boundary(positionSum / cluster.size(), extentMin, extentMax, covered));
        }

        return boundaries;
    }

    /**
     * A logical table boundary derived from clustered ruling lines.
     */
    @Data
    @AllArgsConstructor
    static class Boundary {
        /** The axis position of the boundary (y for horizontal, x for vertical). */
        private float position;
        /** Start of the perpendicular extent covered by the clustered rulings. */
        private float extentMin;
        /** End of the perpendicular extent covered by the clustered rulings. */
        private float extentMax;
        /** Total (union) length covered by the clustered rulings. */
        private float covered;
    }

    /**
     * A visual line of text on the page.
     */
    @Data
    static class TextLineGroup {
        private final List<Word> words = new LinkedList<>();
        private float centerYSum = 0f;

        void add(Word word, float centerY) {
            words.add(word);
            centerYSum += centerY;
        }

        float getCenterY() {
            return words.isEmpty() ? 0f : centerYSum / words.size();
        }

        float getMinY() {
            float min = Float.MAX_VALUE;
            for (Word word : words) {
                min = Math.min(min, Math.min(word.getY1(), word.getY2()));
            }
            return min;
        }

        float getMaxY() {
            float max = -Float.MAX_VALUE;
            for (Word word : words) {
                max = Math.max(max, Math.max(word.getY3(), word.getY4()));
            }
            return max;
        }

        float getMinX() {
            float min = Float.MAX_VALUE;
            for (Word word : words) {
                min = Math.min(min, Math.min(word.getX1(), word.getX4()));
            }
            return min;
        }

        float getMaxX() {
            float max = -Float.MAX_VALUE;
            for (Word word : words) {
                max = Math.max(max, Math.max(word.getX2(), word.getX3()));
            }
            return max;
        }

        String getText() {
            StringBuilder builder = new StringBuilder();
            for (Word word : words) {
                if (builder.length() > 0) {
                    builder.append(' ');
                }
                builder.append(word.getContent());
            }
            return builder.toString();
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.offline;

import com.finboost.bank.statement.parser.config.document.extraction.NativeTablePolicy;
import org.springframework.stereotype.Service;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

import static com.finboost.bank.statement.parser.config.document.extraction.NativeTablePolicy.BORDERED_GRID;
import static com.finboost.bank.statement.parser.config.document.extraction.NativeTablePolicy.BOX_GUIDED;
import static com.finboost.bank.statement.parser.config.document.extraction.NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED;

/**
 * Selects the native transaction-table extraction policies to attempt for the
 * supported bank-format families. The families and their preferred policies are
 * derived from the repository's statement fixture corpus
 * ({@code src/test/resources/pdf-samples-latest}).
 *
 * <p>Each family lists the policies in preference order; every attempted policy is
 * validated before its result is accepted, and the remote ML path remains the
 * default for banks that are not registered here.</p>
 */
@Service
public class NativeExtractionPolicyRegistry {

    private static final Map<String, List<NativeTablePolicy>> POLICIES_BY_BANK_FAMILY = new HashMap<>();

    static {
        // Fully ruled grid layouts (public sector / co-operative bank families).
        List<NativeTablePolicy> borderedFirst = List.of(BORDERED_GRID, BOX_GUIDED, TEXT_ALIGNED_ROW_SELECTED);
        register(borderedFirst,
                "AHMEDNAGAR", "BANDHAN", "BOB", "CBI", "GS_MAHANAGAR_CO_OP_BANK", "INDIAN",
                "INDIAN_OVERSEAS", "PNB", "SBI", "SURYODAY_SMALL_FINANCE_BANK_LTD", "TJSB_BANK", "UNION");

        // Box / vertical-separator guided layouts (large private bank families).
        List<NativeTablePolicy> boxFirst = List.of(BOX_GUIDED, BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register(boxFirst, "AXIS", "HDFC", "ICICI", "IDBI", "KOTAK", "RBL");

        // Text-aligned layouts without usable rulings; rows are selected by anchors.
        List<NativeTablePolicy> textFirst = List.of(TEXT_ALIGNED_ROW_SELECTED, BOX_GUIDED, BORDERED_GRID);
        register(textFirst, "CITI", "DEUSTCHE", "FEDERAL", "IDFC", "INDUSIND", "STANDARD_CHARTERED", "YES");
    }

    private static void register(List<NativeTablePolicy> policies, String... bankCodes) {
        for (String bankCode : bankCodes) {
            POLICIES_BY_BANK_FAMILY.put(bankCode, policies);
        }
    }

    /**
     * Returns the ordered native policies to attempt for a bank code, or an empty
     * list when the bank format family is not supported by the native path.
     */
    public List<NativeTablePolicy> policiesFor(String bankCode) {
        if (bankCode == null || bankCode.isBlank()) {
            return Collections.emptyList();
        }
        String normalized = bankCode.trim().toUpperCase(Locale.ROOT).replaceAll("[\\s-]+", "_");
        return POLICIES_BY_BANK_FAMILY.getOrDefault(normalized, Collections.emptyList());
    }

    public boolean isNativeSupported(String bankCode) {
        return !policiesFor(bankCode).isEmpty();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.offline;

/**
 * Raised when the offline native transaction-table path cannot produce a
 * validated result for a statement, signalling the router to fall back to the
 * remote ML extraction path.
 */
public class NativeExtractionUnsupportedException extends RuntimeException {

    public NativeExtractionUnsupportedException(String message) {
        super(message);
    }

    public NativeExtractionUnsupportedException(String message, Throwable cause) {
        super(message, cause);
    }
}

