package com.finboost.bank.statement.parser.service.document.extraction.offline;

import com.finboost.bank.statement.parser.config.document.extraction.ExtractionMode;
import com.finboost.bank.statement.parser.config.document.extraction.NativeTablePolicy;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.service.bankstatement.InconsistencyFinderService;
import com.finboost.bank.statement.parser.service.document.extraction.DocumentExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.IBankSpecificParsingService;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.AnalyzeDocuments;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Offline (native) document extraction service. Produces the same structured
 * {@link DocumentExtractionResult} as the remote ML path, using only PDFBox and
 * the local layout policies, and carries the result through the same downstream
 * document analysis pipeline. When no policy produces a validated transaction
 * table the service throws {@link NativeExtractionUnsupportedException} so the
 * caller can fall back to the remote ML extraction path.
 */
@Service("nativeDocumentExtractionServiceImpl")
@Slf4j
public class NativeDocumentExtractionServiceImpl implements DocumentExtractionService {

    @Setter(onMethod_ = @Autowired)
    private NativePdfContentReader nativePdfContentReader;

    @Setter(onMethod_ = @Autowired)
    private NativeTransactionTableComposer nativeTransactionTableComposer;

    @Setter(onMethod_ = @Autowired)
    private NativeExtractionPolicyRegistry nativeExtractionPolicyRegistry;

    @Setter(onMethod_ = @Autowired)
    private AnalyzeDocuments analyzeDocuments;

    @Setter(onMethod_ = @Autowired)
    private IBankSpecificParsingService bankSpecificParsingService;

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
        documentExtractionRequest.setStatementFile(bankStatementVO.getDecryptedFile());
        documentExtractionRequest.setBankName(bankStatementVO.getBank());
        try {
            documentExtractionRequest.setStatementFromDate(
                    BankStatementProcessorImpl.parseDate(bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
        } catch (Exception e) {
            log.warn("Failed to parse statement-from-date for native extraction");
        }
        return extractDocument(documentExtractionRequest);
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        return extractDocumentNatively(request, nativeExtractionPolicyRegistry.policiesFor(request.getBankName()));
    }

    /**
     * Attempts the given native policies in order, returning the first result that
     * both composes structured tables and yields consistent transactions.
     *
     * @throws NativeExtractionUnsupportedException when no policy succeeds
     */
    public DocumentExtractionResult extractDocumentNatively(DocumentExtractionRequest request,
                                                            List<NativeTablePolicy> policies) throws IOException {
        if (policies == null || policies.isEmpty()) {
            throw new NativeExtractionUnsupportedException(
                    "No native table policy registered for bank " + request.getBankName());
        }

        List<NativePdfPageContent> pageContents = nativePdfContentReader.read(request.getStatementFile());
        long wordCount = pageContents.stream().mapToLong(page -> page.getWords().size()).sum();
        if (pageContents.isEmpty() || wordCount < 20) {
            throw new NativeExtractionUnsupportedException(
                    "Statement has no extractable text layer (likely scanned); native path unsupported");
        }

        for (NativeTablePolicy policy : policies) {
            try {
                DocumentExtractionResult result = composeResult(pageContents, policy);
                if (result == null) {
                    log.info("Native policy {} produced no candidate tables for bank {}", policy, request.getBankName());
                    continue;
                }

                runDownstreamAnalysis(result, request);

                if (validateTransactions(result)) {
                    result.setExtractionMode(ExtractionMode.NATIVE);
                    result.setNativeTablePolicy(policy);
                    log.info("Native extraction succeeded for bank {} using policy {}", request.getBankName(), policy);
                    return result;
                }
                log.info("Native policy {} did not validate for bank {}", policy, request.getBankName());
            } catch (NativeExtractionUnsupportedException e) {
                throw e;
            } catch (Exception e) {
                log.warn("Native policy {} failed for bank {}: {}", policy, request.getBankName(), e.getMessage());
            }
        }

        throw new NativeExtractionUnsupportedException(
                "No native table policy produced a validated transaction table for bank " + request.getBankName());
    }

    /**
     * Builds the raw {@link DocumentExtractionResult} (pages, words and candidate
     * tables) for a policy, before downstream analysis.
     */
    private DocumentExtractionResult composeResult(List<NativePdfPageContent> pageContents, NativeTablePolicy policy) {
        Map<Integer, Page> pages = new HashMap<>();
        int tablesComposed = 0;

        for (NativePdfPageContent pageContent : pageContents) {
            Page page = new Page();
            page.setPageNumber(pageContent.getPageNumber());
            page.setWidth(pageContent.getWidth());
            page.setHeight(pageContent.getHeight());
            page.setContent(pageContent.getContent());
            page.setWords(new ArrayList<>(pageContent.getWords()));

            Map<Integer, Table> tables = nativeTransactionTableComposer.composeTables(pageContent, policy);
            page.setTables(tables);
            tablesComposed += tables.size();

            pages.put(pageContent.getPageNumber(), page);
        }

        if (tablesComposed == 0) {
            return null;
        }

        DocumentExtractionResult result = new DocumentExtractionResult();
        result.setPages(pages);
        result.setNoOfPages(pageContents.size());
        return result;
    }

    /**
     * Runs the same downstream document analysis pipeline that the remote ML path
     * uses so the native result is carried through identically.
     */
    private void runDownstreamAnalysis(DocumentExtractionResult result, DocumentExtractionRequest request) {
        // Check if the bank statement parsing happens bank specific
        bankSpecificParsingService.identifyBankSpecificStatementProcess(result, request);

        if (result.isSkipFurtherProcessing()) {
            return;
        }

        DocumentExtractionResult preProcessedResultByHeader = analyzeDocuments.preProcessForVerificationByHeader(result, 5);
        if (preProcessedResultByHeader != null && preProcessedResultByHeader.getPreProcessVerificationResult() != null) {
            result.setPreProcessVerificationResult(preProcessedResultByHeader.getPreProcessVerificationResult());
        } else {
            DocumentExtractionResult preprocessedResult = analyzeDocuments.preProcessForVerification(result,
                    result.getNoOfPages() != null ? result.getNoOfPages() : 0);
            if (preprocessedResult != null && preprocessedResult.getPreProcessVerificationResult() != null) {
                result.setPreProcessVerificationResult(preprocessedResult.getPreProcessVerificationResult());
            }
        }

        analyzeDocuments.analyzeDocument(result, true, true, true);
    }

    /**
     * Validates the analysed native result by extracting the transactions with the
     * shared (unchanged) transaction parser and checking balance consistency.
     */
    private boolean validateTransactions(DocumentExtractionResult result) {
        try {
            DocumentExtractionResult copy = result.copy();
            BankStatementVO statementVO = new BankStatementVO();
            statementVO.setDocumentExtractionResult(copy);
            List<BankStatementVO> statementList = new LinkedList<>();
            statementList.add(statementVO);

            BankStatementProcessorImpl.extractTransactions(statementList, false);

            List<BankTransactionVO> transactions = statementVO.getBankTransactions();
            if (transactions == null || transactions.size() < 2) {
                return false;
            }

            Integer inconsistencyCount = InconsistencyFinderService.checkInconsistencyForCount(transactions);
            if (inconsistencyCount != null && inconsistencyCount == 0) {
                return true;
            }

            // The statement may be ordered in the opposite direction; verify the
            // reversed order and flip the flag on the result when it is consistent.
            List<BankTransactionVO> reversedTransactions = new LinkedList<>();
            for (int i = transactions.size() - 1; i >= 0; i--) {
                reversedTransactions.add(transactions.get(i));
            }
            inconsistencyCount = InconsistencyFinderService.checkInconsistencyForCount(reversedTransactions);
            if (inconsistencyCount != null && inconsistencyCount == 0) {
                result.setStatementWithReversedOrder(!result.isStatementWithReversedOrder());
                return true;
            }

            return false;
        } catch (Exception e) {
            log.warn("Native transaction validation failed: {}", e.getMessage());
            return false;
        }
    }
}

