/**
 * Routes document extraction between the offline native transaction-table path
 * and the remote ML path:
 *
 * <ol>
 *     <li>Bank-format families supported by the native path are extracted offline;
 *     when a native layout succeeds its result is used directly and no remote ML
 *     extraction is invoked ({@link ExtractionMode#NATIVE}).</li>
 *     <li>When the native path is attempted but does not produce a validated
 *     result, the remote ML path is used as a fallback
 *     ({@link ExtractionMode#NATIVE_FALLBACK_ML}).</li>
 *     <li>Unknown or unsupported layouts go straight to the remote ML path, which
 *     remains the default ({@link ExtractionMode#ML}).</li>
 * </ol>
 */
@Service("routingDocumentExtractionServiceImpl")
@Slf4j
public class RoutingDocumentExtractionServiceImpl implements DocumentExtractionService {

    private DocumentExtractionService mlDocumentExtractionService;

    @Setter(onMethod_ = @Autowired)
    private NativeDocumentExtractionServiceImpl nativeDocumentExtractionService;

    @Setter(onMethod_ = @Autowired)
    private NativeExtractionPolicyRegistry nativeExtractionPolicyRegistry;

    @Autowired
    @Qualifier("azureDocumentExtractionServiceImpl")
    public void setMlDocumentExtractionService(DocumentExtractionService mlDocumentExtractionService) {
        this.mlDocumentExtractionService = mlDocumentExtractionService;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
        documentExtractionRequest.setStatementFile(bankStatementVO.getDecryptedFile());
        documentExtractionRequest.setBankName(bankStatementVO.getBank());
        try {
            documentExtractionRequest.setStatementFromDate(
                    BankStatementProcessorImpl.parseDate(bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
        } catch (Exception e) {
            log.warn("Failed to parse statement-from-date from date string {}",
                    bankStatementVO.getBankAccountDetailsVO() != null
                            ? bankStatementVO.getBankAccountDetailsVO().getStatementFrom() : null);
        }
        return extractDocument(documentExtractionRequest);
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        List<NativeTablePolicy> nativePolicies = nativeExtractionPolicyRegistry.policiesFor(request.getBankName());

        boolean nativeAttempted = false;
        if (!nativePolicies.isEmpty()) {
            nativeAttempted = true;
            try {
                DocumentExtractionResult nativeResult =
                        nativeDocumentExtractionService.extractDocumentNatively(request, nativePolicies);
                if (nativeResult != null) {
                    // Diagnostics (mode + policy) are set by the native service.
                    return nativeResult;
                }
            } catch (NativeExtractionUnsupportedException e) {
                log.info("Native extraction unsupported for bank {}; falling back to ML extraction: {}",
                        request.getBankName(), e.getMessage());
            } catch (Exception e) {
                log.warn("Native extraction failed for bank {}; falling back to ML extraction: {}",
                        request.getBankName(), e.getMessage());
            }
        }

        DocumentExtractionResult mlResult = mlDocumentExtractionService.extractDocument(request);
        if (mlResult != null) {
            mlResult.setExtractionMode(nativeAttempted ? ExtractionMode.NATIVE_FALLBACK_ML : ExtractionMode.ML);
            mlResult.setNativeTablePolicy(null);
        }
        return mlResult;
    }
}

