/**
 * Builds per-statement extraction diagnostics (native / ML / native-to-ML
 * fallback) for the upload statement API response.
 */
private static List<StatementParseResponseDTO> buildStatementDiagnostics(List<BankStatementVO> bankStatementVOList) {
    List<StatementParseResponseDTO> statementDiagnostics = new ArrayList<>();
    if (bankStatementVOList == null) {
        return statementDiagnostics;
    }
    for (BankStatementVO bankStatementVO : bankStatementVOList) {
        if (bankStatementVO == null) {
            continue;
        }
        StatementParseResponseDTO statementDTO = new StatementParseResponseDTO();
        statementDTO.setFileId(bankStatementVO.getFileId());
        statementDTO.setFileName(bankStatementVO.getOriginalFileName());
        statementDTO.setBank(bankStatementVO.getBank());
        DocumentExtractionResult extractionResult = bankStatementVO.getDocumentExtractionResult();
        if (extractionResult != null) {
            statementDTO.setExtractionMode(extractionResult.getExtractionMode() != null
                    ? extractionResult.getExtractionMode().name() : null);
            statementDTO.setNativeTablePolicy(extractionResult.getNativeTablePolicy() != null
                    ? extractionResult.getNativeTablePolicy().name() : null);
        }
        statementDiagnostics.add(statementDTO);
    }
    return statementDiagnostics;
}

/**
 * Resolves the account-level extraction mode from the modes of the statements
 * that were grouped into the account: NATIVE when all statements were extracted
 * natively, ML when all used the remote ML path, and NATIVE_FALLBACK_ML when
 * any statement fell back (or the statements used a mix of engines).
 */
private static String resolveAccountExtractionMode(List<BankStatementVO> statements) {
    if (statements == null || statements.isEmpty()) {
        return null;
    }
    Set<ExtractionMode> modes = statements.stream()
            .map(BankStatementVO::getDocumentExtractionResult)
            .filter(Objects::nonNull)
            .map(DocumentExtractionResult::getExtractionMode)
            .filter(Objects::nonNull)
            .collect(Collectors.toSet());
    if (modes.isEmpty()) {
        return null;
    }
    if (modes.size() == 1) {
        return modes.iterator().next().name();
    }
    return ExtractionMode.NATIVE_FALLBACK_ML.name();
}

