import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankSpecificParsingServiceImpl;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.bank.*;
import com.finboost.bank.statement.parser.service.document.extraction.offline.*;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.*;

import java.io.File;
import java.lang.reflect.Field;
import java.util.LinkedList;
import java.util.List;

public class NativeRunner {

    public static void main(String[] args) throws Exception {
        File pdf = new File(args[0]);
        String bank = args[1];

        NativeDocumentExtractionServiceImpl svc = buildService();
        NativeExtractionPolicyRegistry registry = new NativeExtractionPolicyRegistry();

        DocumentExtractionRequest req = new DocumentExtractionRequest();
        req.setStatementFile(pdf);
        req.setBankName(bank);

        try {
            DocumentExtractionResult res = svc.extractDocumentNatively(req, registry.policiesFor(bank));
            BankStatementVO vo = new BankStatementVO();
            vo.setDocumentExtractionResult(res);
            List<BankStatementVO> list = new LinkedList<>();
            list.add(vo);
            BankStatementProcessorImpl.extractTransactions(list);
            List<BankTransactionVO> txns = vo.getBankTransactions();
            System.out.println("RESULT SUCCESS policy=" + res.getNativeTablePolicy()
                    + " mode=" + res.getExtractionMode()
                    + " txns=" + (txns == null ? 0 : txns.size()));
            if (txns != null) {
                int shown = 0;
                for (BankTransactionVO t : txns) {
                    if (shown++ >= 4) break;
                    String d = t.getTransactionDescription();
                    System.out.println("  " + t.getTransactionDate() + " | " + t.getTransactionType()
                            + " | " + t.getTransactionAmount() + " | bal " + t.getTransactionBalance()
                            + " | " + (d == null ? "" : d.substring(0, Math.min(45, d.length()))));
                }
            }
        } catch (Exception e) {
            System.out.println("RESULT UNSUPPORTED: " + e.getMessage());
        }
    }

    static NativeDocumentExtractionServiceImpl buildService() throws Exception {
        ColumnTypeIdentifier cti = new ColumnTypeIdentifier();
        HistogramColumnDetectionService hist = new HistogramColumnDetectionService();

        BankTransactionTableHeaderIdentifier hdr = new BankTransactionTableHeaderIdentifier();
        hdr.setColumnTypeIdentifier(cti);
        BankTransactionTableFooterIdentifier ftr = new BankTransactionTableFooterIdentifier();
        BankTransactionColumnTypeIdentifier btcti = new BankTransactionColumnTypeIdentifier();
        BankTransactionTableIdentifier btti = new BankTransactionTableIdentifier();
        TableColumnNormalizer tcn = new TableColumnNormalizer();
        TableRowNormalizer trn = new TableRowNormalizer();
        BankTransactionRowNormalizer btrn = new BankTransactionRowNormalizer();
        StatementBasicDetailExtractor sbde = new StatementBasicDetailExtractor();

        BankSpecificParsingServiceImpl bsp = new BankSpecificParsingServiceImpl();
        HdfcBankUtil hdfc = new HdfcBankUtil();
        setField(hdfc, "tableColumnNormalizer", tcn);
        setField(hdfc, "tableRowNormalizer", trn);
        bsp.setHdfcBankUtil(hdfc);
        SaraswatBankUtil saraswat = new SaraswatBankUtil();
        saraswat.setBankTransactionRowNormalizer(btrn);
        saraswat.setBankTransactionTableHeaderIdentifier(hdr);
        bsp.setSaraswatBankUtil(saraswat);
        StandardCharteredBankUtil scb = new StandardCharteredBankUtil();
        scb.setBankTransactionRowNormalizer(btrn);
        bsp.setStandardCharteredBankUtil(scb);
        bsp.setCatholicSyrianBankUtil(new CatholicSyrianBankUtil());
        MayBankUtil may = new MayBankUtil();
        may.setBankTransactionRowNormalizer(btrn);
        may.setBankTransactionTableHeaderIdentifier(hdr);
        bsp.setMayBankUtil(may);
        PublicBankUtil pub = new PublicBankUtil();
        pub.setBankTransactionRowNormalizer(btrn);
        pub.setBankTransactionTableHeaderIdentifier(hdr);
        bsp.setPublicBankUtil(pub);

        AnalyzeDocuments ad = new AnalyzeDocuments();
        ad.setColumnTypeIdentifier(cti);
        ad.setBankTransactionColumnTypeIdentifier(btcti);
        ad.setBankTransactionTableIdentifier(btti);
        ad.setTableColumnNormalizer(tcn);
        ad.setTableRowNormalizer(trn);
        ad.setBankTransactionRowNormalizer(btrn);
        ad.setBankTransactionTableHeaderIdentifier(hdr);
        ad.setBankTransactionTableFooterIdentifier(ftr);
        ad.setStatementBasicDetailExtractor(sbde);
        ad.setBankSpecificParsingService(bsp);

        NativeTransactionTableComposer composer = new NativeTransactionTableComposer();
        composer.setHistogramColumnDetectionService(hist);

        NativeDocumentExtractionServiceImpl svc = new NativeDocumentExtractionServiceImpl();
        svc.setNativePdfContentReader(new NativePdfContentReader());
        svc.setNativeTransactionTableComposer(composer);
        svc.setNativeExtractionPolicyRegistry(new NativeExtractionPolicyRegistry());
        svc.setAnalyzeDocuments(ad);
        svc.setBankSpecificParsingService(bsp);
        return svc;
    }

    static void setField(Object target, String name, Object value) throws Exception {
        Field f = target.getClass().getDeclaredField(name);
        f.setAccessible(true);
        f.set(target, value);
    }
}

