/**
 * Counts the text lines of a page that carry both a date-like and an
 * amount-like token. These "anchor" lines approximate the number of
 * transaction rows on the page and are used to verify that a native result is
 * reasonably complete before it is accepted.
 */
public int countTransactionAnchorLines(NativePdfPageContent page) {
    int count = 0;
    for (TextLineGroup line : groupWordsIntoLines(page.getWords())) {
        if (containsDateToken(line) && containsAmountToken(line)) {
            count++;
        }
    }
    return count;
}

