private boolean removeOpeningBalanceIfNeeded(List<BankTransactionVO> transactions) {
    if (transactions.isEmpty()) {
        return false;
    }

    BankTransactionVO firstTxn = transactions.get(0);
    if (firstTxn.getTransactionDescription().toLowerCase().matches(".*opening\\s*balance.*")) {
        transactions.remove(0);
        return true;
    }
    return false;
}

private static boolean checkInconsistency(BankTransactionVO currentTxn, BankTransactionVO nextTxn) {
    BigDecimal currentBalance = currentTxn.getTransactionBalance();
    BigDecimal nextBalance = nextTxn.getTransactionBalance();
    BigDecimal amount = nextTxn.getTransactionAmount();

    boolean isInconsistent = false;
    if (TransactionType.CREDIT.equals(nextTxn.getTransactionType())) {
        // For CREDIT: currentBalance + amount should equal nextBalance
        BigDecimal expectedBalance = currentBalance.add(amount).setScale(2, RoundingMode.HALF_UP);
        isInconsistent = !isBalanceConsistent(expectedBalance, nextBalance);
    } else {
        // For DEBIT: currentBalance - amount should equal nextBalance
        BigDecimal expectedBalance = currentBalance.subtract(amount).setScale(2, RoundingMode.HALF_UP);
        isInconsistent = !isBalanceConsistent(expectedBalance, nextBalance);
    }
    return isInconsistent;
}


