    /**
     * Verifies that every page with a substantial number of date+amount anchor
     * lines contributed rows to a recognised transaction table.
     */
    private boolean validatePageCoverage(DocumentExtractionResult result, Map<Integer, Integer> anchorLinesPerPage) {
        if (result.getPages() == null) {
            return false;
        }
        for (Map.Entry<Integer, Integer> entry : anchorLinesPerPage.entrySet()) {
            int pageAnchors = entry.getValue() != null ? entry.getValue() : 0;
            if (pageAnchors < 8) {
                continue;
            }
            Page page = result.getPages().get(entry.getKey());
            int transactionRows = 0;
            if (page != null && page.getTables() != null) {
                for (Table table : page.getTables().values()) {
                    if (table != null && table.getIsTransactionTable() && table.getCells() != null) {
                        transactionRows += table.getCells().size();
                    }
                }
            }
            if (transactionRows < pageAnchors * 0.5) {
                log.info("Native result rejected: page {} has {} anchor lines but only {} transaction rows",
                        entry.getKey(), pageAnchors, transactionRows);
                return false;
            }
        }
        return true;
    }
